            if line:
                try:
                    with open(line, 'rb') as f:
                        raw_stats = marshal.load(f)
                    self.stats = stats_factory(raw_stats)
                    try:
                        file_stats = os.stat(line)
                        arg = time.ctime(file_stats.st_mtime) + "    " + line
                    except Exception:
                        arg = line
