    def cmd_quit(self, arg):
        self.push('221 quit ok')
        self.shutdown()

    def cmd_abor(self, arg):
        self.push('226 abor ok')

    def cmd_stor(self, arg):
        self.push('125 stor ok')

    def cmd_rest(self, arg):
