    def test_yiq_to_rgb_clamping(self):
        values = [
            # rgb, yiq (invalid YIQ values clamped to RGB range)
            ((1.0, 0.0, 1.0), (0.0, 0.5, 1.0)),
            ((0.0, 1.0, 0.0), (0.25, -1.0, -1.0)),
