    def test_refcycle(self):
        # A generator caught in a refcycle gets finalized anyway.
        old_garbage = gc.garbage[:]
        finalized = False
        def gen():
            nonlocal finalized
            try:
                g = yield
                yield 1
            finally:
                finalized = True

        g = gen()
        next(g)
        g.send(g)
        self.assertGreaterEqual(sys.getrefcount(g), 2)
        self.assertFalse(finalized)
        del g
        support.gc_collect()
        self.assertTrue(finalized)
        self.assertEqual(gc.garbage, old_garbage)

    def test_lambda_generator(self):
        # bpo-23192, gh-119897: Test that a lambda returning a generator behaves
        # like the equivalent function
        f = lambda: (yield 1)
        self.assertIsInstance(f(), types.GeneratorType)
        self.assertEqual(next(f()), 1)

        def g(): return (yield 1)

        # test 'yield from'
        f2 = lambda: (yield from g())
        def g2(): return (yield from g())

        f3 = lambda: (yield from f())
        def g3(): return (yield from f())

        for gen_fun in (f, g, f2, g2, f3, g3):
            gen = gen_fun()
            self.assertEqual(next(gen), 1)
            with self.assertRaises(StopIteration) as cm:
                gen.send(2)
            self.assertEqual(cm.exception.value, 2)

    def test_generator_resurrect(self):
        # Test that a resurrected generator still has a valid gi_code
        resurrected = []

        # Resurrect a generator in a finalizer
        exec(textwrap.dedent("""
            def gen():
                try:
                    yield
                except:
                    resurrected.append(g)

            g = gen()
            next(g)
        """), {"resurrected": resurrected})

        support.gc_collect()

        self.assertEqual(len(resurrected), 1)
        self.assertIsInstance(resurrected[0].gi_code, types.CodeType)

    def test_exhausted_generator_frame_cycle(self):
        def g():
            yield

        generator = g()
        frame = generator.gi_frame
        self.assertIsNone(frame.f_back)
        next(generator)
        self.assertIsNone(frame.f_back)
        next(generator, None)
        self.assertIsNone(frame.f_back)


class GeneratorTest(unittest.TestCase):

    def test_name(self):
